if(cv.contact?.length) header.push(new Paragraph({children:[new TextRun({text:cv.contact.slice(0,3).join("   |   "),size:17,color:"aaaaaa"})],spacing:{after:180},shading:{fill:BLACK,type:ShadingType.CLEAR}}));

const sb=[];
const rsec=(t)=> new Paragraph({children:[new TextRun({text:t,bold:true,size:19,color:BLACK,characterSpacing:80})],spacing:{before:200,after:60},border:{bottom:{style:BorderStyle.DOUBLE,size:3,color:DARK}}});
if(cv.summary){
  sb.push(rsec("HAKKIMDA"));
  sb.push(new Paragraph({children:[new TextRun({text:cv.summary,size:17,color:GRAY})],spacing:{after:120}}));
}
sb.push(rsec("BECERİLER"));
(cv.skills||[]).forEach(sk=>sb.push(new Paragraph({children:[new TextRun({text:"▪ "+String(sk),size:17,color:DARK})],spacing:{after:45}})));
if(cv.languages?.length){
  sb.push(rsec("DİLLER"));
  cv.languages.forEach(l=>sb.push(new Paragraph({children:[new TextRun({text:String(l),size:17,color:DARK})],spacing:{after:45}})));
}
if(cv.education?.length){
  sb.push(rsec("EĞİTİM"));
  cv.education.forEach(edu=>{
    sb.push(new Paragraph({children:[new TextRun({text:edu.degree||"",bold:true,size:17,color:DARK})],spacing:{before:80,after:30}}));
    if(edu.school) sb.push(new Paragraph({children:[new TextRun({text:edu.school,size:16,color:GRAY})],spacing:{after:30}}));
    if(edu.date) sb.push(new Paragraph({children:[new TextRun({text:edu.date,size:15,color:GRAY,italics:true})],spacing:{after:80}}));
  });
}

const mn=[];
const mh=(t)=> new Paragraph({children:[new TextRun({text:t,bold:true,size:22,color:BLACK,characterSpacing:80})],spacing:{before:220,after:80},border:{bottom:{style:BorderStyle.DOUBLE,size:3,color:DARK}}});
if(cv.experience?.length){
  mn.push(mh("İŞ DENEYİMİ"));
  cv.experience.forEach(exp=>{
    mn.push(new Paragraph({children:[new TextRun({text:"● ",color:DARK,size:19}),new TextRun({text:exp.title||"",bold:true,size:21,color:DARK}),new TextRun({text:exp.date?"  —  "+exp.date:"",size:17,color:GRAY,italics:true})],spacing:{before:100,after:40}}));
    if(exp.company) mn.push(new Paragraph({children:[new TextRun({text:exp.company,size:18,color:GRAY})],spacing:{after:50}}));
    (exp.bullets||[]).forEach(b=>mn.push(new Paragraph({children:[new TextRun({text:"• "+b,size:18,color:"444444"})],spacing:{after:40},indent:{left:200}})));
    mn.push(new Paragraph({spacing:{after:80}}));
  });
}
if(cv.courses?.length){
  mn.push(mh("KURSLAR & SERTİFİKALAR"));
  cv.courses.forEach(cr=>{
    mn.push(new Paragraph({children:[new TextRun({text:"● ",color:DARK,size:19}),new TextRun({text:cr.name||"",bold:true,size:21,color:DARK}),new TextRun({text:cr.date?"  —  "+cr.date:"",size:17,color:GRAY,italics:true})],spacing:{before:100,after:40}}));
    if(cr.provider) mn.push(new Paragraph({children:[new TextRun({text:cr.provider,size:18,color:GRAY})],spacing:{after:80}}));
  });
}

