  new TableCell({width:{size:3400,type:WidthType.DXA},shading:{fill:"f9f9f9",type:ShadingType.CLEAR},borders:{...NB(),right:{style:BorderStyle.SINGLE,size:6,color:LGRAY}},verticalAlign:VerticalAlign.TOP,margins:{top:500,bottom:720,left:500,right:440},children:sb}),
  new TableCell({width:{size:8506,type:WidthType.DXA},shading:{fill:"ffffff",type:ShadingType.CLEAR},borders:NB(),verticalAlign:VerticalAlign.TOP,margins:{top:500,bottom:720,left:500,right:440},children:mn}),
]})]});
