  new Table({width:{size:11906,type:WidthType.DXA},borders:NB(),rows:[new TableRow({children:[
    new TableCell({width:{size:11906,type:WidthType.DXA},shading:{fill:BLACK,type:ShadingType.CLEAR},borders:NB(),margins:{top:0,bottom:0,left:0,right:0},children:header}),
  ]})]}),
